/* Original later-stage, multi-step challenges. They are not copied examination questions. */
const stretch={
linear: N('Exam reasoning','A school rents buses. Company A charges ₹2500 plus ₹20 per student; company B charges ₹1000 plus ₹35 per student. How many students make the two prices equal?',100,'students','Set the complete cost expressions equal.','2500 + 20n = 1000 + 35n → 1500 = 15n → n = 100.','JEE-inspired stretch'),
ratios: N('Exam reasoning','A 30 L mixture has milk:water = 3:2. How many litres of water must be added to make the ratio 3:4?',12,'L','The amount of milk does not change when water is added.','Milk = 18 L and water = 12 L. The target requires 24 L water, so add 12 L.','JEE-inspired stretch'),
quadratics: N('Exam reasoning','The roots of x² − 8x + k = 0 differ by 2. Find k.',15,'','The roots sum to 8 and differ by 2.','The roots are 3 and 5. Their product is k = 15.','JEE-inspired stretch'),
coordinates: N('Exam reasoning','Point P lies on the x-axis and is equidistant from A(2,3) and B(8,5). Find the x-coordinate of P.',19/3,'','Let P = (x,0) and equate the squared distances.','(x−2)² + 9 = (x−8)² + 25 → 12x = 76 → x = 19/3.','JEE-inspired stretch'),
trigonometry: N('Exam reasoning','A right triangle has sin θ = 3/5 for an acute angle θ. Find (1 − cos θ)/(1 + cos θ) as a fraction or decimal.',1/9,'','Find cos θ using sin² θ + cos² θ = 1.','cos θ = 4/5, so (1−4/5)/(1+4/5) = (1/5)/(9/5) = 1/9.','JEE-inspired stretch'),
probability: N('Exam reasoning','A bag has 3 red and 2 blue balls. Two are drawn without replacement. Given that at least one is red, what is the probability both are red?',1/3,'','Count equally likely unordered pairs and exclude the blue–blue pair.','There are 10 pairs in total, one blue–blue pair and 3 red–red pairs. Conditional probability = 3/9 = 1/3.','JEE-inspired stretch'),
statistics: N('Exam reasoning','Six numbers have mean 12. Removing one value makes the remaining mean 10. What value was removed?',22,'','Recover both totals from mean × count.','Original total = 72. Remaining total = 50. Removed value = 22.','JEE-inspired stretch'),
exponents: N('Exam reasoning','Solve 2^(x+1) + 2^x = 48.',4,'','Factor out 2^x.','3 × 2^x = 48 → 2^x = 16 → x = 4.','JEE-inspired stretch'),
sequences: N('Exam reasoning','An arithmetic sequence has third term 11 and seventh term 27. What is the sum of its first 10 terms?',210,'','Find the common difference and first term before summing.','4d = 16, so d = 4 and a₁ = 3. S₁₀ = 10[2(3)+9(4)]/2 = 210.','JEE-inspired stretch'),
calculus: N('Exam reasoning','A rectangle with perimeter 20 m has sides x and y. Using a derivative, find its maximum area.',25,'m²','Write y in terms of x, differentiate xy, and check the endpoints.','y = 10−x, A = 10x−x². A′ = 10−2x = 0 at x = 5; A″ = −2 and endpoints give zero. Maximum area is 25 m².','JEE-inspired stretch'),
matter: N('Exam reasoning','Two immiscible liquids of masses 60 g and 40 g have densities 1.2 and 0.8 g/mL. If their volumes add, what is the average density of the combined system?',1,'g/mL','Calculate each liquid’s volume, then use total mass / total volume.','Volumes are 60/1.2 = 50 mL and 40/0.8 = 50 mL. The combined density is 100/100 = 1 g/mL.','JEE-inspired stretch'),
atoms: N('Exam reasoning','A neutral atom has 20 electrons and its mass number is 44. How many neutrons are in its nucleus?',24,'neutrons','A neutral atom has as many protons as electrons.','It has 20 protons. Neutrons = 44 − 20 = 24.','JEE-inspired stretch'),
bonding: Q('Exam reasoning','A metal forms M³⁺ ions and a non-metal forms X²⁻ ions. Which formula and ion counts make a neutral compound?',['MX with one of each','M₂X₃ with 2 M³⁺ and 3 X²⁻','M₃X₂ with 3 M³⁺ and 2 X²⁻','M₂X with 2 M³⁺ and 1 X²⁻'],1,'The smallest common multiple of the charge magnitudes is 6.','2 M³⁺ contribute +6 and 3 X²⁻ contribute −6, giving M₂X₃.','JEE-inspired stretch'),
reactions: N('Exam reasoning','For 2Al + 3Cl₂ → 2AlCl₃, 8 Al atoms react with 15 Cl₂ molecules. How many Cl₂ molecules remain after the maximum number of complete batches?',3,'molecules','Find how many complete sets of 2 Al and 3 Cl₂ can react.','Eight Al atoms allow 4 batches, requiring 12 Cl₂ molecules. 15 − 12 = 3 Cl₂ remain.','JEE-inspired stretch'),
moles: N('Exam reasoning','For N₂ + 3H₂ → 2NH₃, 28 g N₂ reacts with 3 g H₂. Use molar masses 28, 2 and 17 g/mol. Find the theoretical mass of NH₃.',17,'g','Find moles of each reactant and identify the limiting reactant.','N₂ = 1 mol and H₂ = 1.5 mol. H₂ limits the reaction, producing (2/3)(1.5) = 1 mol NH₃ = 17 g.','JEE-inspired stretch'),
solutions: N('Exam reasoning','How many mL of 2.0 mol/L NaCl solution should be mixed with 100 mL of 0.5 mol/L NaCl to make a 1.0 mol/L mixture? Assume volumes add.',50,'mL','Use moles before mixing = moles in the final mixture.','2x + 0.5(100) = 1(x+100), using mL consistently. Thus x = 50 mL.','JEE-inspired stretch'),
acids: N('Exam reasoning','Mix 100 mL of 0.10 mol/L HCl with 100 mL of 0.05 mol/L NaOH at 25°C. Assume complete reaction and additive volumes. What is the excess [H⁺]?',.025,'mol/L','Subtract reacting moles before dividing by total litres.','Initial H⁺ = 0.010 mol and OH⁻ = 0.005 mol. Excess H⁺ = 0.005 mol in 0.200 L = 0.025 mol/L.','JEE-inspired stretch'),
energy: N('Exam reasoning','Mix 100 g water at 80°C with 100 g water at 20°C. Assume equal specific heat and no heat loss. Find the final temperature.',50,'°C','Heat lost by hot water equals heat gained by cold water.','100c(80−T) = 100c(T−20), so 80−T = T−20 and T = 50°C.','JEE-inspired stretch'),
rates: N('Exam reasoning','A reaction has rate = k[A]²[B]. If [A] is tripled and [B] is halved at constant temperature, by what factor does the rate change?',4.5,'times','Apply both concentration factors to the rate law.','Rate factor = 3² × 1/2 = 9/2 = 4.5.','JEE-inspired stretch'),
carbon: N('Exam reasoning','On complete combustion, 0.5 mol of an acyclic alkane produces 2 mol CO₂. How many carbon atoms are in each alkane molecule?',4,'carbon atoms','Each carbon atom produces one CO₂ molecule.','Carbon number n = 2/0.5 = 4. The alkane is C₄H₁₀.','JEE-inspired stretch')
};
for(const [id,q] of Object.entries(stretch)){const t=TOPICS.find(x=>x.id===id);if(!t)throw new Error('Missing stretch topic '+id);t.questions.push(q)}
/* Single-digit integer-response format observed in the reference paper. */
const integerStretches=[
['quadratics',N('Exam integer','How many integers x satisfy x² − 5x + 6 ≤ 0? Enter one integer from 0 to 9.',2,'','Factor the quadratic, then include the endpoints.','(x − 2)(x − 3) ≤ 0 for 2 ≤ x ≤ 3. The integers are 2 and 3, so the answer is 2.','JEE-inspired stretch')],
['moles',N('Exam integer','One mole of Na₂CO₃·xH₂O has mass 196 g. Anhydrous Na₂CO₃ has molar mass 106 g/mol and water 18 g/mol. Find integer x.',5,'','Subtract the anhydrous mass, then divide by 18.','196 = 106 + 18x, so x = 90/18 = 5. The dot denotes water of crystallisation.','JEE-inspired stretch')],
['magnetism',N('Exam integer','For a straight wire, F = BIL sin θ. Magnetic field and current are each doubled; the angle changes from 30° to 90°, while length stays fixed. By what integer factor does the force change?',8,'','Multiply the field factor, current factor, and sine ratio.','The factor is 2 × 2 × (sin 90° / sin 30°) = 2 × 2 × 2 = 8.','JEE-inspired stretch')]
];
for(const [id,q] of integerStretches){q.format='integer-digit';TOPICS.find(t=>t.id===id).questions.push(q)}
